const msg = $input.first().json;
const m2 = msg["category_m2"];
const intent = msg["intent"];
const missing = msg["missing"] || [];

if (missing.length) {
  return {
    chat_id: msg.chat_id,
    needs_user_input: true,
    missing,
    reply_text: missing.includes("m2") ? "To help you list this flat for sale, which size category describes it? 86, 96, 92, or 120 m²?" : msg.reply_text
  };
}

return { chat_id: msg.chat_id, reply_text: msg.reply_text, intent, category_m2: m2, needs_user_input: false };

const item = $input.first().json;
const m2 = item["category_m2"];

if (!m2) {
  return [{ json: { chat_id: item.chat_id, reply_text: item.reply_text } }];
}

let text = item.reply_text || "Here are matching flats:";

// Replace this block with your real inventory source: Google Sheet, Airtable, Postgres, CSV, etc.
const inventory = {
  86: [{ title: "86 A", address: "Street 1" }],
  96: [{ title: "96 X", address: "Street 2" }],
  92: [{ title: "92 Y", address: "Street 3" }],
  120: [{ title: "120 Z", address: "Street 4" }]
};

const matches = inventory[m2] || [];
if (matches.length) {
  text = matches.map((f, i) => `${i + 1}. ${f.title} - ${f.address}`).join("\n");
} else {
  text = `No current flats available in the ${m2} m² category.`;
}

return [{ json: { chat_id: item.chat_id, reply_text: text } }];
